package app.hushgram.extension.instagram.settings;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.BitmapShader;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Shader;
import android.util.Base64;

/** The user-supplied assets/instaprime-icon.png, embedded because the extension adds no resources. */
final class InstaPrimeIcon {
    private static volatile Bitmap decoded;
    private static final String PNG =
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "" +
            "";

    private InstaPrimeIcon() { }

    static Bitmap bitmap() {
        Bitmap known = decoded;
        if (known != null) return known;
        byte[] png = Base64.decode(PNG, Base64.DEFAULT);
        known = BitmapFactory.decodeByteArray(png, 0, png.length);
        if (known == null) throw new IllegalStateException("InstaPrime icon could not be decoded");
        Bitmap rounded = Bitmap.createBitmap(known.getWidth(), known.getHeight(), Bitmap.Config.ARGB_8888);
        Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);
        paint.setShader(new BitmapShader(known, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP));
        float radius = Math.min(known.getWidth(), known.getHeight()) * 0.14f;
        new Canvas(rounded).drawRoundRect(new RectF(0, 0, rounded.getWidth(), rounded.getHeight()), radius, radius, paint);
        decoded = rounded;
        return rounded;
    }
}
